// Rate-law catalogue wrapper: types, lookup, provenance. The data lives in kinetics.gen.ts (generated by
// scripts/port-kinetics.py from docs/research); nothing here retypes a number. The rate functions are in src/sim/chem/kinetics.ts.
import type { Conf } from '../sim/types';
import { KINETICS_GEN } from './kinetics.gen';

export type RateForm =
  | 'temkin' | 'eklund' | 'first_order' | 'cstr_arrhenius'
  | 'vbf' | 'power_rev' | 'xf' | 'luong' | 'gauze_selectivity' | 'third_order';

/** Variant of a first-order law (one per catalyst): Ea in J/mol, kref in 1/s at the law's Tref. */
export interface RateVariant { catalyst: string; Ea: number; kref: number; kconf: Conf }

export interface RateLawRec {
  id: string;
  form: RateForm;
  /** 'must' laws are implemented; 'stretch' laws are stub entries (rate() returns NaN). */
  tier: 'must' | 'stretch';
  /** Catalogue reaction ids, in the order rate() returns them. */
  reactions: readonly string[];
  basis: string;
  catalysts: readonly string[];
  /** Role (N2, H2, NH3, SO2, O2, SO3, A) -> species id. */
  species: Readonly<Record<string, string>>;
  params: Readonly<Record<string, number>>;
  variants?: readonly RateVariant[];
  range: string;
  src: string;
  conf: Conf;
  fit: null | { note: string; ratioMin: number; ratioMax: number };
}

export const KINETICS: readonly RateLawRec[] = KINETICS_GEN as unknown as readonly RateLawRec[];
export const KINETICS_IDS: readonly string[] = KINETICS.map((l) => l.id);
export const MUST_SHIP_LAWS: readonly RateLawRec[] = KINETICS.filter((l) => l.tier === 'must');

const BY_ID: Record<string, RateLawRec> = {};
for (const l of KINETICS) BY_ID[l.id] = l;

export function findLaw(id: string): RateLawRec | undefined { return Object.prototype.hasOwnProperty.call(BY_ID, id) ? BY_ID[id] : undefined; }
export function lawOf(id: string): RateLawRec {
  const l = findLaw(id);
  if (l === undefined) throw new Error('unknown rate law: ' + id);
  return l;
}

export interface LawProvenanceRow { id: string; tier: 'must' | 'stretch'; src: string; conf: Conf }
export function lawProvenanceReport(): LawProvenanceRow[] {
  return KINETICS.map((l) => ({ id: l.id, tier: l.tier, src: l.src, conf: l.conf }));
}
